func (s *Service) checkoutReferencedHelmSources(valueFiles []string, sha string, targetRevision string, q *apiclient.RepoServerAppDetailsQuery, tempPaths utilio.TempPaths) error {
	if len(q.RefSources) == 0 {
		return nil
	}

	// Determine which ref names are actually referenced by the value files.
	referenced := make(map[string]bool)
	for _, valueFile := range valueFiles {
		if !strings.HasPrefix(valueFile, "$") {
			continue
		}
		referenced[strings.Split(valueFile, "/")[0]] = true
	}

	// Collect the referenced ref source names and process them in lexicographically sorted order to keep error
	// messages deterministic.
	refNames := make([]string, 0, len(referenced))
	for refName := range q.RefSources {
		if referenced[refName] {
			refNames = append(refNames, refName)
		}
	}
	sort.Strings(refNames)

	// seen tracks the repositories that have already been resolved (and checked out), keyed by normalized repo URL.
	seen := make(map[string]helmRefSource)
	for _, refName := range refNames {
		refSourceMapping := q.RefSources[refName]
		normalizedRepoURL := git.NormalizeGitURL(refSourceMapping.Repo.Repo)

		// Non-git referenced repositories (e.g. OCI) are already made available elsewhere; only verify a cached path
		// exists for them without performing any git operations or creating a new path.
		if refSourceMapping.Repo.Type != "" && refSourceMapping.Repo.Type != "git" {
			tempPaths.GetPathIfExists(normalizedRepoURL)
			continue
		}

		gitClient, referencedCommitSHA, err := s.newClientResolveRevision(&refSourceMapping.Repo, refSourceMapping.TargetRevision, git.WithCache(s.cache, !q.NoRevisionCache && !q.NoCache))
		if err != nil {
			return fmt.Errorf("error setting up git client for %s and resolving revision %s: %w", refSourceMapping.Repo.Repo, refSourceMapping.TargetRevision, err)
		}

		if existing, ok := seen[normalizedRepoURL]; ok {
			if existing.commitSHA != referencedCommitSHA {
				return fmt.Errorf("cannot reference multiple revisions for the same repository (%s references %q which resolves to %q while %s references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, existing.key, existing.revision, existing.commitSHA)
			}
			// Same repository at the same revision - it has already been checked out.
			continue
		}

		if git.NormalizeGitURL(q.Repo.Repo) == normalizedRepoURL && referencedCommitSHA != sha {
			return fmt.Errorf("cannot reference a different revision of the same repository (%s references %q which resolves to %q while the application references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, targetRevision, sha)
		}

		closer, err := s.repoLock.Lock(gitClient.Root(), referencedCommitSHA, true, func(clean bool) (goio.Closer, error) {
			return s.checkoutRevision(gitClient, referencedCommitSHA, s.initConstants.SubmoduleEnabled, refSourceMapping.Repo.Depth, clean)
		})
		if err != nil {
			return fmt.Errorf("failed to acquire lock for referenced repo %q: %w", refSourceMapping.Repo.Repo, err)
		}
		defer utilio.Close(closer)

		seen[normalizedRepoURL] = helmRefSource{revision: refSourceMapping.TargetRevision, commitSHA: referencedCommitSHA, key: refName}
	}

	return nil
}

